import type { ExternalLink } from "@/lib/schema";

/**
 * Patient education links, by record id: NCCN Guidelines for Patients (titles and addresses from NCCN's public list,
 * https://www.nccn.org/patientresources/patient-resources/guidelines-for-patients), NCI PDQ patient summaries (from the seven
 * PDQ category pages at https://www.cancer.gov/publications/pdq/information-summaries) and the Patient Education Sheets of
 * ONS, NCODA, HOPA and ACCC (from NCODA's public resource list, https://ncoda.org/wp-json/wp/v2/resource, sheets under
 * ncoda.org/pes/). Read on 4 November 2026 for the gap census (docs/proposals/gap-census-2026-11.md, education-resources).
 *
 * Only titles and addresses are held; no guide's or sheet's content is reproduced. Every address answered HTTP 200 without a
 * redirect when checked that day. A sheet is linked to a medicine record only where the sheet names that medicine alone
 * (or a fixed combination, formulation or named regimen the record is about); multi-drug regimen sheets with no record of
 * their own are not linked to each component. Where a record already carried the address, it is not repeated here.
 * src/data/index.ts appends these to each record's `links`, skipping any address the record already holds.
 */
